<span class="line"><span style="color:#E06C75;">      &quot;inputModes&quot;</span><span style="color:#ABB2BF;">: [</span><span style="color:#98C379;">&quot;text/plain&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;application/pdf&quot;</span><span style="color:#ABB2BF;">],</span></span>
